!function($,Drupal){"use strict";Drupal.behaviors.etecsa_faq={attach:function(context,settings){var url=window.location.href,faq;if(-1!=url.indexOf("preguntas-frecuentes?clientef")){var id=url.split("=");$("#edit-clientes").val(id[1])}var tema=$("#edit-temasfaq option:selected").text();$(".faq").each((function(){$(this).hasClass(tema)?$(this).show():$(this).hide()})),$("#edit-temasfaq").on("change",(function(){var tema=this.options[this.selectedIndex].text;$(".faq").each((function(){$(this).hasClass(tema)?$(this).show():$(this).hide()}))}))}}}(jQuery,Drupal);